#!/usr/bin/env node
/**
 * The conformance oracle of the screen contract (ADR-0038 decision 6, REQ-SCR-008): compares the
 * accessibility trees each platform's UI suite recorded (`e2e/conformance/<platform>.json`) with
 * what the contract in `crates/rust-core/src/screens` declares, and reports every difference in one
 * run. Zero dependencies, like `tooling/spec-check`.
 *
 * Inputs, both generated by `pnpm tokens:sync` and never copied by hand:
 * - the contract: `screens.json` in the iOS UI-test resources (the same bytes as the Android
 *   assets' copy). It is the one generated form a script can read without a compiler, and it
 *   carries `PLATFORM_MINIMUMS` as `platform_minimums`;
 * - the copy: `packages/core-ts/src/generated/strings.json`, every locale's resolved strings.
 *
 * Usage: `node tooling/screens-check/screens-check.mjs [--dir <manifests>]` (default
 * `e2e/conformance`). A platform without a manifest is reported, not failed, so the web check runs
 * alone. The manifest shape and how each platform writes it: `e2e/conformance/README.md`.
 */
import { existsSync, readFileSync, realpathSync } from 'node:fs';
import { join, relative } from 'node:path';
import { pathToFileURL } from 'node:url';

export const PLATFORMS = ['web', 'ios', 'android'];
export const CONTRACT_PATH = 'apps/ios/Tests/TranVotingDemoUITests/Resources/screens.json';
export const STRINGS_PATH = 'packages/core-ts/src/generated/strings.json';
export const MANIFEST_DIR = 'e2e/conformance';

/**
 * The roles each element kind may take, per platform: the platform's own vocabulary for the
 * semantic kind the contract declares (REQ-SCR-003).
 */
export const ROLES = {
  // Chromium's computed ARIA roles (`Accessibility.getFullAXTree`). A text has no role of its own:
  // Chromium reports a `span` as `generic` and a `p` as `paragraph`.
  web: {
    field: ['textbox', 'spinbutton', 'combobox', 'searchbox'],
    // An in-page link is the web's button for moving focus (the skip link, REQ-A11Y-010).
    button: ['button', 'link'],
    text: ['generic', 'paragraph', 'note'],
    live_region: ['status', 'alert', 'log'],
    banner: ['status', 'alert', 'region', 'note'],
    toast: ['status', 'alert'],
    dialog: ['dialog', 'alertdialog'],
    segmented: ['radiogroup', 'group', 'tablist', 'toolbar'],
    progress: ['progressbar'],
  },
  // `XCUIElement.ElementType` case names. SwiftUI exposes a container it gives an identifier as
  // `other`; a segmented control drawn as a row of buttons is such a container.
  ios: {
    field: ['textField', 'secureTextField', 'searchField', 'textView'],
    button: ['button'],
    text: ['staticText'],
    live_region: ['staticText'],
    banner: ['staticText', 'other', 'group'],
    toast: ['other', 'group', 'staticText'],
    dialog: ['alert', 'sheet', 'other'],
    segmented: ['segmentedControl', 'other', 'group'],
    progress: ['progressIndicator', 'activityIndicator'],
  },
  // Compose `Role` names, and for nodes without one what their semantics make them
  // (`ConformanceManifest.kt`): `TextField` takes `SetText`, `Text` carries text, `ProgressBar`
  // a range, `None` is a container. A Material button declares `Button`.
  android: {
    field: ['TextField'],
    button: ['Button'],
    text: ['Text'],
    live_region: ['Text'],
    banner: ['Text', 'None'],
    toast: ['Text', 'None'],
    dialog: ['None'],
    segmented: ['None'],
    progress: ['ProgressBar'],
  },
};

/**
 * Kinds whose accessible name is their label. The others carry changing content (a verdict, a
 * status, a role) that the label names: their name and value together must contain the label.
 */
const NAMED_BY_LABEL = new Set(['field', 'button', 'segmented', 'progress', 'dialog']);

/**
 * Interactive nodes the platform places and the app does not, so the contract cannot declare them.
 * Keep it short; every entry says why.
 */
export const PLATFORM_OWNED = [
  {
    platform: 'ios',
    reason: 'the system keyboard, its keys and its suggestion bar belong to iOS, not to the screen',
    matches: (node) =>
      node.role === 'key' ||
      (node.under ?? []).includes('keyboard') ||
      IOS_INPUT_VIEWS.has(node.within),
  },
  {
    platform: 'ios',
    reason: 'a navigation bar back button is drawn by UINavigationController',
    matches: (node) => (node.under ?? []).includes('navigationBar') && node.role === 'button',
  },
];

/** UIKit's identifiers for the keyboard's own views; the suggestion bar's buttons sit inside them. */
const IOS_INPUT_VIEWS = new Set(['inputView', 'SystemInputAssistantView', 'CenterPageView']);

/** How far a measured size may fall short of a minimum: frames are laid out in device pixels. */
const EPSILON = 0.01;

const normalize = (text) => (text ?? '').replace(/\s+/g, ' ').trim();

/** The contract as the checker needs it: every element by id, every screen, every minimum. */
export function indexContract(contract) {
  const elements = new Map();
  for (const screen of contract.screens)
    for (const element of screen.elements) elements.set(element.id, element);
  return {
    screens: contract.screens,
    elements,
    minimums: contract.platform_minimums,
    unreached: new Map((contract.unreached_states ?? []).map((u) => [u.state, u.reason])),
  };
}

/** The contract as one platform sees it: each screen keeps only the elements it offers there. */
export function forPlatform(index, platform) {
  return {
    ...index,
    screens: index.screens.map((screen) => ({
      ...screen,
      elements: screen.elements.filter((element) => element.platforms.includes(platform)),
    })),
  };
}

/** A label key in `locale`, falling back to English as every platform does (REQ-I18N-002). */
export function resolve(strings, key, locale = 'en') {
  return strings[locale]?.[key] ?? strings.en?.[key];
}

/**
 * The screen a snapshot shows: the contract screen whose always-present ids overlap most with the
 * snapshot's ids; on a tie, the one with the fewest always-present elements missing. A tie that
 * remains is reported instead of guessed.
 *
 * A snapshot with no always-present id at all is a modal state: every platform hides the screen
 * beneath an open dialog from assistive technology. It belongs to `previous`, the screen the same
 * scenario's last snapshot showed, when that screen declares every id it shows; otherwise it
 * matches nothing and is reported.
 */
export function detectScreen(contract, snapshot, previous) {
  const ids = new Set(snapshot.elements.map((node) => node.id).filter(Boolean));
  const modal = () => {
    const declared = new Set(previous?.elements.map((element) => element.id));
    return previous && ids.size > 0 && [...ids].every((id) => declared.has(id))
      ? { screen: previous, modal: true }
      : { error: 'no contract screen matches its ids' };
  };
  const ranked = contract.screens
    .map((screen) => {
      const always = screen.elements.filter((element) => element.presence === 'always');
      const overlap = always.filter((element) => ids.has(element.id)).length;
      return { screen, overlap, missing: always.length - overlap };
    })
    .sort((a, b) => b.overlap - a.overlap || a.missing - b.missing);
  const [best, next] = ranked;
  if (!best || best.overlap === 0) return modal();
  if (next && next.overlap === best.overlap && next.missing === best.missing)
    return { error: `ambiguous: ${best.screen.id} or ${next.screen.id}` };
  return { screen: best.screen };
}

/** The declared segmented control a node is an option of: inside it, or `<control id>-<option>`. */
function optionOf(index, node) {
  const owner = (id) => (index.elements.get(id)?.kind === 'segmented' ? id : undefined);
  if (node.id) {
    for (const [id, element] of index.elements)
      if (element.kind === 'segmented' && node.id.startsWith(`${id}-`)) return id;
    return undefined;
  }
  return node.within ? owner(node.within) : undefined;
}

/**
 * Every difference between one manifest and the contract: `{ snapshot, element, rule, expected,
 * actual }`. `seen` collects, per screen, the conditional elements observed (for "never observed").
 */
export function checkManifest(contract, strings, manifest) {
  const platform = manifest.platform;
  const failures = [];
  const seen = new Map();
  const minimum = contract.minimums.find((entry) => entry.platform === platform);
  if (!PLATFORMS.includes(platform) || !minimum)
    return {
      failures: [
        {
          snapshot: '-',
          element: '-',
          rule: 'platform',
          expected: PLATFORMS.join('|'),
          actual: platform,
        },
      ],
      seen,
    };
  const index = forPlatform(contract, platform);
  const roles = ROLES[platform];

  /** Scenario → the screen its last snapshot showed, for a modal state's screen. */
  const last = new Map();
  for (const snapshot of manifest.snapshots) {
    const where = `${snapshot.scenario} [${snapshot.phase}]`;
    const fail = (element, rule, expected, actual) =>
      failures.push({ snapshot: where, element, rule, expected, actual });
    const detected = detectScreen(index, snapshot, last.get(snapshot.scenario));
    if (detected.error) {
      fail('-', 'screen', 'one contract screen', detected.error);
      continue;
    }
    const { screen } = detected;
    last.set(snapshot.scenario, screen);
    const locale = snapshot.locale ?? 'en';
    const observed = seen.get(screen.id) ?? new Set();
    seen.set(screen.id, observed);
    const present = new Set(snapshot.elements.map((node) => node.id).filter(Boolean));

    // Beneath a dialog the screen's own elements are hidden, not missing.
    for (const element of detected.modal ? [] : screen.elements) {
      if (element.presence === 'always' && !present.has(element.id))
        fail(element.id, 'required present', `on ${screen.id}`, 'absent');
    }

    for (const node of snapshot.elements) {
      const element = node.id ? index.elements.get(node.id) : undefined;
      const option = element ? undefined : optionOf(index, node);
      if (option) {
        checkTouch(node, index.elements.get(option).touch, minimum, (rule, e, a) =>
          fail(node.id ?? `${option} option "${normalize(node.name)}"`, rule, e, a)
        );
        continue;
      }
      if (!element || !element.platforms.includes(platform)) {
        // A non-interactive node's own id (SwiftUI names an SF Symbol after itself) is not ours.
        if (!node.interactive) continue;
        if (PLATFORM_OWNED.some((owned) => owned.platform === platform && owned.matches(node)))
          continue;
        fail(
          node.id ?? `${node.role} "${normalize(node.name)}"`,
          'undeclared interactive',
          `an element the contract declares${element ? ` on ${platform}` : ''}`,
          `${node.role}${node.id ? ` "${node.id}"` : ''}`
        );
        continue;
      }
      if (element.presence === 'when') observed.add(element.id);
      const allowed = roles[element.kind] ?? [];
      if (!allowed.includes(node.role))
        fail(element.id, 'role', `${element.kind}: ${allowed.join('|')}`, node.role);
      checkName(node, element, resolve(strings, element.label, locale), (e, a) =>
        fail(element.id, 'name', e, a)
      );
      checkTouch(node, element.touch, minimum, (rule, e, a) => fail(element.id, rule, e, a));
    }
  }
  return { failures, seen };
}

function checkName(node, element, label, fail) {
  if (label === undefined) return fail(`a string for ${element.label}`, 'no such key');
  const name = normalize(node.name);
  const expected = normalize(label);
  if (NAMED_BY_LABEL.has(element.kind)) {
    if (name !== expected) fail(`"${expected}"`, `"${name}"`);
    return;
  }
  // Content the label names: iOS reads label then value, Android description then text, the web
  // name then the text inside; joined, they must contain the label.
  const announced = normalize(`${node.name ?? ''} ${node.value ?? ''}`);
  if (!announced.includes(expected)) fail(`containing "${expected}"`, `"${announced}"`);
}

function checkTouch(node, touch, minimum, fail) {
  if (touch === 'none') return;
  const floor = touch === 'primary' ? minimum.primary_action : minimum.control;
  if (node.unit !== minimum.unit) return fail('unit', minimum.unit, node.unit);
  const { width, height } = node.frame ?? {};
  if (!(width + EPSILON >= floor && height + EPSILON >= floor))
    fail('touch minimum', `${floor}×${floor} ${minimum.unit}`, `${width}×${height}`);
}

/** Conditional elements every platform's scenarios must reach at least once, per screen. */
export function neverObserved(contract, seen, platform) {
  const missing = [];
  const notes = [];
  for (const screen of forPlatform(contract, platform).screens) {
    if (!seen.has(screen.id)) continue; // a screen the platform never showed has no states to reach
    for (const element of screen.elements) {
      if (element.presence !== 'when' || seen.get(screen.id).has(element.id)) continue;
      const reason = contract.unreached.get(element.state);
      if (reason) {
        notes.push(
          `  · ${screen.id} › ${element.id}: state ${element.state} is unreached (${reason})`
        );
        continue;
      }
      missing.push({
        snapshot: `screen ${screen.id}`,
        element: element.id,
        rule: 'never observed',
        expected: `present in some snapshot (state ${element.state})`,
        actual: 'never',
      });
    }
  }
  return { missing, notes };
}

/** Checks every manifest in `dir`; returns the report lines and whether all passed. */
export function run(root, dir = join(root, MANIFEST_DIR)) {
  const index = indexContract(JSON.parse(readFileSync(join(root, CONTRACT_PATH), 'utf8')));
  const strings = JSON.parse(readFileSync(join(root, STRINGS_PATH), 'utf8'));
  const lines = [];
  let ok = true;
  for (const platform of PLATFORMS) {
    const file = join(dir, `${platform}.json`);
    if (!existsSync(file)) {
      lines.push(`screens-check: ${platform}: no manifest (${relative(root, file)})`);
      continue;
    }
    const manifest = JSON.parse(readFileSync(file, 'utf8'));
    const { failures, seen } = checkManifest(index, strings, manifest);
    const { missing, notes } = neverObserved(index, seen, manifest.platform);
    failures.push(...missing);
    ok &&= failures.length === 0;
    lines.push(...notes);
    for (const f of failures)
      lines.push(
        `  ✗ ${relative(root, file)} › ${f.snapshot} › ${f.element} › ${f.rule}: expected ${f.expected}, got ${f.actual}`
      );
    lines.push(
      `screens-check: ${platform}: ${manifest.snapshots.length} snapshots, ${failures.length} difference${failures.length === 1 ? '' : 's'}`
    );
  }
  return { lines, ok };
}

function main(argv) {
  const at = argv.indexOf('--dir');
  const root = process.cwd();
  const { lines, ok } = run(root, at === -1 ? undefined : argv[at + 1]);
  for (const line of lines) (line.startsWith('  ✗') ? console.error : console.log)(line);
  if (!ok) process.exit(1);
  console.log('screens-check: ok');
}

// realpath: a symlinked path (macOS /var -> /private/var) must still count as running this file.
if (process.argv[1] && import.meta.url === pathToFileURL(realpathSync(process.argv[1])).href)
  main(process.argv.slice(2));
